uniform float speed : 0.0 .. 10.0 = 3.0;
uniform float width : 0.05 .. 0.5 = 0.2;
uniform vec3 red : color = 1.0, 0.0, 0.0;
uniform vec3 blue : color = 0.0, 0.0, 1.0;

state fixed ph;

void update() {
    ph = fract(ph + fixed(dt * speed));
}

vec3 shade(Led led) {
    // led.uv.x is roughly the angle around the cylinder (0..1)
    // We want a spinning beam.
    // Use the angle from UV.x. 
    // In a helix, UV.x maps to the rotation.

    fixed angle = fixed(led.uv.x);
    fixed beam_center = ph;

    // Distance in circular space
    fixed diff = abs(angle - beam_center);
    // Handle wrap-around for the circle
    if (diff > fixed(0.5)) {
        diff = fixed(1.0) - diff;
    }

    // Create a sharp beam using a clamp-based ramp (fast replacement for smoothstep)
    // width is 0..1 relative to the circle
    fixed mask = clamp((fixed(width) - diff) * fixed(10.0), fixed(0.0), fixed(1.0));

    // Alternate red and blue based on the phase
    // If ph is in [0, 0.5), use red. If [0.5, 1.0), use blue.
    // We'll use a hard switch to make it look like police lights.
    vec3 col = (ph < fixed(0.5)) ? red : blue;

    return col * float(mask);
}
